def make_inputs(raw83,raw41,original_mass,stop_count,fit_positions,score_positions):
    """No labels accepted: fit-only statistics and two-domain structural weights."""
    fi=np.asarray(fit_positions,int);hi=np.asarray(score_positions,int);stop=fi<stop_count;assert stop.any() and (~stop).any();mass=np.zeros(len(fi));mass[stop]=.5*original_mass[fi[stop]]/original_mass[fi[stop]].sum();mass[~stop]=.5*original_mass[fi[~stop]]/original_mass[fi[~stop]].sum();nstop=int(stop.sum());weights=mass*nstop
    m83=np.average(raw83[fi[stop]],axis=0,weights=mass[stop]);s83=np.sqrt(np.average((raw83[fi[stop]]-m83)**2,axis=0,weights=mass[stop]));s83[s83<1e-8]=1.;m41=np.average(raw41[fi],axis=0,weights=mass);s41=np.sqrt(np.average((raw41[fi]-m41)**2,axis=0,weights=mass));s41[s41<1e-8]=1.
    transform=lambda ii:np.c_[(raw83[ii]-m83)/s83,(raw41[ii]-m41)/s41]
    xf,xh=transform(fi),transform(hi);assert xf.shape==(len(fi),124) and xh.shape==(len(hi),124);assert np.isfinite(xf.astype(np.float32)).all() and np.isfinite(xh.astype(np.float32)).all();assert abs(weights.sum()-nstop)<1e-8
    return dict(fit_X=xf,score_X=xh,mean83=m83,scale83=s83,mean41=m41,scale41=s41,event_weights=weights,fit_STOP_mask=stop,inner_STOP_count=np.array([nstop]))
